DIY_BOOK({"v": 1, "id": "how-to-build-lego-towers-tyler-g", "title": "How to build lego towers", "author": "Tyler G.", "cat": "art", "hook": "If you want to become more creative then you should get this book. This book is a step by step guide on how to make lego towers.", "diff": 1, "mins": 5, "color": "#f0553a", "cover": "data:image/jpeg;base64,", "materials": ["10 2X4 Lego bricks", "5 2x2 Lego bricks"], "steps": [{"img": "data:image/jpeg;base64,", "text": "Put the bricks ontop of eachother.", "tip": "", "warn": "You might hurt your finger if you pinch your finger!"}, {"img": "data:image/jpeg;base64,", "text": "Add another ontop.", "tip": "", "warn": ""}, {"img": "data:image/jpeg;base64,", "text": "Reapeat steps one and two.", "tip": "", "warn": "Dont put the two ontop of eachother."}, {"img": "data:image/jpeg;base64,", "text": "Put two 2x4 infrount of you.", "tip": "", "warn": "Dont drop them it might hurt your feet!"}, {"img": "data:image/jpeg;base64,", "text": "Put them ontop of eachother.", "tip": "", "warn": ""}, {"img": "data:image/jpeg;base64,", "text": "Get a 2x4 and a 2x2.", "tip": "", "warn": ""}, {"img": "data:image/jpeg;base64,", "text": "Put the 2x2 on the 4 studes closest to eather side.", "tip": "", "warn": ""}, {"img": "data:image/jpeg;base64,", "text": "Grab a 2x4 and a 2x2 and put the 2x2 in the middle of the 2x4.", "tip": "", "warn": ""}, {"img": "data:image/jpeg;base64,", "text": "Get three 2x2s.", "tip": "", "warn": ""}, {"img": "data:image/jpeg;base64,", "text": "Put them in a triangle pattern.", "tip": "", "warn": ""}], "quiz": [{"q": "How many pieces do you need for the first tower.", "choices": ["2", "3", "4"], "answer": 1}, {"q": "How many pieces do you need for the second tower.", "choices": ["2", "5", "32"], "answer": 0}, {"q": "how many pieces do you need for the last tower", "choices": ["3", "84", "12"], "answer": 0}], "updated": 1795095418669, "thumb": "data:image/jpeg;base64,"});
